actions.script:
const L = (text) => ec.l10n.localize(text)
const out = callSessionId ? ec.service.sync().name('org.moqui.call.CallServices.get#Call').parameter('callSessionId', callSessionId)
    .requireNewTransaction(true).disableAuthz().call() || {} : {}
ec.message.clearErrors()
call = out.call || null
const STATES = {ringing: L('Ringing'), active: L('In progress'), ended: L('Ended')}
stateText = call ? (STATES[call.status] || call.status) + (call.endReason ? ' (' + call.endReason + ')' : '') : ''
startedText = call && call.startedDate ? ec.l10n.format(new Date(Number(call.startedDate)), 'MMM d, h:mm a') : ''
kindText = call ? (call.video ? L('Video call') : L('Audio call')) : ''
// W8: the call's media encryption, and each person's encryption device in an end-to-end encrypted call
encrypted = !!call && !!call.e2ee
encryptionText = encrypted ? L('End-to-end encrypted: only the people in the call hear and see it (no recording, captions, phones or guests)')
    : L('Encrypted to the server, which forwards it')
const deviceOf = (p) => { const leg = Array.from(p.legs || []).find((l) => l.status === 'answered' && l.type === 'web'); return leg ? leg.deviceId : null }
peopleList = call ? Array.from(call.participants || []).map((p) => ({name: p.displayName,
    stateText: (p.inCall ? L('In the call') : p.ringing ? L('Ringing') : L('Not in the call')) +
        (encrypted && p.inCall ? ' · ' + (deviceOf(p) ? L('device') + ' ' + deviceOf(p) : L('no encryption device')) : '')})) : []
canAnswer = !!call && call.status !== 'ended' && call.myLegStatus === 'offered' && !encrypted
mustUseBrowser = !!call && call.status !== 'ended' && call.myLegStatus === 'offered' && encrypted
canLeave = !!call && call.status !== 'ended' && call.myLegStatus === 'answered'
// W6: the call's captions, as the user in it sees them
const captionOut = call && call.status !== 'ended' ? ec.service.sync().name('org.moqui.call.CallCaptionServices.get#CaptionState')
    .parameter('callSessionId', callSessionId).requireNewTransaction(true).disableAuthz().call() || {} : {}
ec.message.clearErrors()
const captions = captionOut.captions || null
captionsShown = !!captions && captions.allowed === true
captionsOn = captionsShown && captions.on === true
let starter = ''
if (captionsOn && captions.startedByUserId) {
    const account = ec.entity.find('moqui.security.UserAccount').condition('userId', captions.startedByUserId).disableAuthz().one()
    starter = account ? account.userFullName || account.username || '' : ''
}
const by = captions && captions.local ? L('transcribed on this server')
    : ec.resource.expand('transcribed by ${provider}', '', {provider: (captions && captions.providerLabel) || L('the speech service')})
captionsText = !captionsShown ? '' : captionsOn
    ? L('Captions are on') + (starter ? ' (' + ec.resource.expand('turned on by ${name}', '', {name: starter}) + ')' : '') + ': ' + by
        + '. ' + L('The lines show in the browser.')
    : L('Captions are off')
canCaptions = captionsShown && canLeave
